(()=>{const host=document.getElementById('L08-lab');if(!host)return;const zh=document.documentElement.lang.startsWith('zh'),tr=(a,b)=>zh?a:b,defaults={fold:4,factor:1.9,thresholdLog:6};let p={...defaults},state={};const controls={};for(const k in p){controls[k]=host.querySelector('#L08-'+k);controls[k].addEventListener('input',()=>set({[k]:Number(controls[k].value)}));}function set(v){for(const k in p)if(k in v)p[k]=Math.max(Number(controls[k].min),Math.min(Number(controls[k].max),Number(v[k])));draw();return state;}function draw(){for(const k in p){controls[k].value=p[k];host.querySelector('[data-value="'+k+'"]').textContent=p[k].toFixed(2);}const h=10**p.thresholdLog,c1=Math.log(h/100)/Math.log(1.9),c2=Math.log(h/(100*p.fold))/Math.log(p.factor);state={...p,controlCq:c1,treatedCq:c2,naiveFold:2**(c1-c2),correctedFold:(h/p.factor**c2)/(h/1.9**c1)};const x=n=>85+n*18,y=v=>380-(v-2)*52;let lines='',marks='';for(const [n0,f,col]of[[100,1.9,'#186e83'],[100*p.fold,p.factor,'#cd803f']]){let d='';for(let j=0;j<=600;j++){const n=j/20,v=Math.log10(n0)+n*Math.log10(f);if(v>8)break;d+=(j?'L':'M')+x(n).toFixed(2)+','+y(v).toFixed(2);}lines+=`<path d="${d}" fill="none" stroke="${col}" stroke-width="3"/>`;}for(let j=2;j<=8;j++)marks+=`<line x1="85" x2="625" y1="${y(j)}" y2="${y(j)}" stroke="#dde3e5"/><text x="70" y="${y(j)+5}" text-anchor="end">10<tspan dy="-6" font-size="12">${j}</tspan></text>`;for(const n of[0,5,10,15,20,25,30])marks+=`<text x="${x(n)}" y="407" text-anchor="middle">${n}</text>`;host.querySelector('svg').innerHTML=`<rect width="760" height="470" fill="#faf9f5"/><g fill="#263e48" font-size="17"><text x="85" y="30">${tr('净信号 / a.u.（对数轴）','Net signal / a.u. (log axis)')}</text>${marks}${lines}<line x1="85" x2="625" y1="${y(p.thresholdLog)}" y2="${y(p.thresholdLog)}" stroke="#8160a1" stroke-width="2" stroke-dasharray="6 4"/><circle cx="${x(c1)}" cy="${y(p.thresholdLog)}" r="6" fill="#186e83"/><circle cx="${x(c2)}" cy="${y(p.thresholdLog)}" r="6" fill="#cd803f"/><text x="355" y="445" text-anchor="middle">${tr('循环数','Cycle')}</text></g>`;host.querySelector('[data-result]').textContent=tr(`蓝色Cq ${c1.toFixed(3)}，橙色Cq ${c2.toFixed(3)}；统一用2的幂：${state.naiveFold.toFixed(3)}倍；按各自效率回推：${state.correctedFold.toFixed(3)}倍；真实${p.fold.toFixed(2)}倍。`,`Blue Cq ${c1.toFixed(3)}, orange Cq ${c2.toFixed(3)}; assuming powers of 2: ${state.naiveFold.toFixed(3)}×; correcting each efficiency: ${state.correctedFold.toFixed(3)}×; truth ${p.fold.toFixed(2)}×.`);}host.querySelector('#L08-threshold-up').addEventListener('click',()=>set({thresholdLog:Math.min(7,p.thresholdLog+1)}));host.querySelector('#L08-reset').addEventListener('click',()=>set(defaults));window.CourseLab={set,state:()=>({...state}),reset:()=>set(defaults)};draw();})();
